1. [CmdletBinding()]
2. param(
3.     [switch]$Setup,
4.     [switch]$FixGhAuth,
5.     [switch]$Json,
6.     [Alias("h")]
7.     [switch]$Help,
8.     [Parameter(ValueFromRemainingArguments = $true)]
9.     [string[]]$RemainingArgs
10. )
11. 
12. Set-StrictMode -Version Latest
13. $ErrorActionPreference = "Stop"
14. 
15. function Show-Usage {
16.     Write-Host ""
17.     Write-Host "Tech stack readiness script" -ForegroundColor Cyan
18.     Write-Host "==========================="
19.     Write-Host ""
20.     Write-Host "Usage:"
21.     Write-Host "  .\scripts\tech-stack-readiness.ps1 [options]"
22.     Write-Host ""
23.     Write-Host "Options:"
24.     Write-Host "  -Setup       Run update/setup commands, then report readiness"
25.     Write-Host "  -FixGhAuth   Remove GITHUB_TOKEN from current session if set"
26.     Write-Host "  -Json        Output results as JSON"
27.     Write-Host "  -Help        Show this help"
28.     Write-Host ""
29.     Write-Host "Examples:"
30.     Write-Host "  .\scripts\tech-stack-readiness.ps1"
31.     Write-Host "  .\scripts\tech-stack-readiness.ps1 -Setup"
32.     Write-Host "  .\scripts\tech-stack-readiness.ps1 -FixGhAuth"
33.     Write-Host "  .\scripts\tech-stack-readiness.ps1 -Json"
34.     Write-Host "  .\scripts\tech-stack-readiness.ps1 --help"
35.     Write-Host ""
36. }
37. 
38. if ($Help -or ($RemainingArgs -contains "--help") -or ($RemainingArgs -contains "-h")) {
39.     Show-Usage
40.     return
41. }
42. 
43. function Normalize-Version {
44.     param([string]$Value)
45.     if ([string]::IsNullOrWhiteSpace($Value)) { return $null }
46.     $clean = $Value.Trim()
47.     $clean = $clean -replace '^[vV]', ''
48.     $clean = ($clean -split '[+ -]')[0]
49.     try { return [version]$clean } catch { return $null }
50. }
51. 
52. function Compare-Version {
53.     param(
54.         [string]$Actual,
55.         [string]$Minimum
56.     )
57.     $a = Normalize-Version $Actual
58.     $m = Normalize-Version $Minimum
59.     if (-not $a -or -not $m) { return $null }
60.     return ($a -ge $m)
61. }
62. 
63. function Get-CommandTextOutput {
64.     param(
65.         [string]$Name,
66.         [string[]]$CommandArgs = @()
67.     )
68.     try {
69.         $null = Get-Command $Name -ErrorAction Stop
70.         return (& $Name @CommandArgs 2>&1 | Out-String).Trim()
71.     } catch {
72.         return $null
73.     }
74. }
75. 
76. function Add-Result {
77.     param(
78.         [System.Collections.Generic.List[object]]$List,
79.         [string]$Category,
80.         [string]$Name,
81.         [string]$Installed,
82.         [string]$Required,
83.         [string]$Status,
84.         [string]$Notes
85.     )
86.     $List.Add([pscustomobject]@{
87.             Category  = $Category
88.             Name      = $Name
89.             Installed = $Installed
90.             Required  = $Required
91.             Status    = $Status
92.             Notes     = $Notes
93.         })
94. }
95. 
96. function Parse-VersionFromRegex {
97.     param(
98.         [string]$InputText,
99.         [string]$Pattern
100.     )
101.     if ([string]::IsNullOrWhiteSpace($InputText)) { return $null }
102.     $m = [regex]::Match($InputText, $Pattern)
103.     if ($m.Success -and $m.Groups.Count -gt 1) { return $m.Groups[1].Value.Trim() }
104.     return $null
105. }
106. 
107. function Remove-Ansi {
108.     param([string]$Text)
109.     if ($null -eq $Text) { return $null }
110.     return ($Text -replace '\x1B\[[0-9;?]*[ -/]*[@-~]', '')
111. }
112. 
113. function Get-PluginVersionFromLocalInstall {
114.     param([string]$PluginKey)
115. 
116.     $parts = $PluginKey.Split("@")
117.     if ($parts.Count -ne 2) { return $null }
118.     $pluginName = $parts[0]
119.     $marketplace = $parts[1]
120. 
121.     $root = Join-Path $env:USERPROFILE ".copilot\installed-plugins\$marketplace\$pluginName"
122.     if (-not (Test-Path $root)) { return $null }
123. 
124.     $jsonCandidates = Get-ChildItem $root -Recurse -Filter "plugin.json" -ErrorAction SilentlyContinue
125.     foreach ($file in $jsonCandidates) {
126.         try {
127.             $obj = Get-Content $file.FullName -Raw | ConvertFrom-Json
128.             if ($obj.name -eq $pluginName -and $obj.version) {
129.                 return [string]$obj.version
130.             }
131.         } catch {
132.             continue
133.         }
134.     }
135.     return $null
136. }
137. 
138. if ($FixGhAuth -and (Test-Path Env:GITHUB_TOKEN)) {
139.     Remove-Item Env:GITHUB_TOKEN -ErrorAction SilentlyContinue
140.     Write-Host "Removed GITHUB_TOKEN from current session environment."
141. }
142. 
143. if ($Setup) {
144.     Write-Host "Running update/setup actions..." -ForegroundColor Cyan
145. 
146.     $wingetIds = @(
147.         "Microsoft.AzureCLI",
148.         "Microsoft.Azd",
149.         "OpenJS.NodeJS.22",
150.         "GitHub.cli"
151.     )
152.     foreach ($id in $wingetIds) {
153.         try {
154.             Write-Host "winget upgrade $id"
155.             & winget upgrade --id $id --accept-package-agreements --accept-source-agreements 2>&1 | Out-Host
156.         } catch {
157.             Write-Warning "winget upgrade failed for ${id}: $($_.Exception.Message)"
158.         }
159.     }
160. 
161.     try {
162.         Write-Host "pac install latest"
163.         & pac install latest 2>&1 | Out-Host
164.     } catch {
165.         Write-Warning "pac install latest failed: $($_.Exception.Message)"
166.     }
167. 
168.     try {
169.         Write-Host "npm install -g @microsoft/dataverse@latest"
170.         & npm install -g @microsoft/dataverse@latest 2>&1 | Out-Host
171.     } catch {
172.         Write-Warning "Dataverse CLI npm update failed: $($_.Exception.Message)"
173.     }
174. 
175.     try {
176.         Write-Host "copilot plugin update --all"
177.         & copilot plugin update --all 2>&1 | Out-Host
178.     } catch {
179.         Write-Warning "Plugin update failed (often a lock issue if Copilot is open): $($_.Exception.Message)"
180.     }
181. 
182.     # Entire: add bucket, install/upgrade, enable in repo, install skills
183.     try {
184.         $scoopBuckets = & scoop bucket list 2>&1 | Out-String
185.         if ($scoopBuckets -notmatch '\bentire\b') {
186.             Write-Host "scoop bucket add entire"
187.             & scoop bucket add entire https://github.com/entireio/scoop-bucket.git 2>&1 | Out-Host
188.         }
189.         # Migrate from old package name 'cli' to 'entire' if needed
190.         $oldInstalled = & scoop list 2>&1 | Out-String
191.         if ($oldInstalled -match '\bcli\b.*entire') {
192.             Write-Host "scoop uninstall cli  (migrating to entire/entire)"
193.             & scoop uninstall cli 2>&1 | Out-Host
194.         }
195.         Write-Host "scoop install entire/entire"
196.         & scoop install entire/entire 2>&1 | Out-Host
197.     } catch {
198.         Write-Warning "Entire install/upgrade failed: $($_.Exception.Message)"
199.     }
200. 
201.     try {
202.         $entireStatus = & entire status 2>&1 | Out-String
203.         if ($entireStatus -notmatch 'Enabled') {
204.             Write-Host "entire enable -y --agent copilot-cli"
205.             & entire enable -y --agent copilot-cli 2>&1 | Out-Host
206.         }
207.     } catch {
208.         Write-Warning "entire enable failed: $($_.Exception.Message)"
209.     }
210. 
211.     try {
212.         Write-Host "npx skills add https://github.com/entireio/skills --all"
213.         & npx skills add https://github.com/entireio/skills --all 2>&1 | Out-Host
214.         # Move skills to canonical Copilot folder if written elsewhere
215.         $skillsDst = Join-Path $env:USERPROFILE '.copilot\skills'
216.         if (!(Test-Path $skillsDst)) { New-Item -ItemType Directory -Path $skillsDst | Out-Null }
217.         @('.agents', '.claude', 'agent') | ForEach-Object {
218.             $src = Join-Path $PSScriptRoot "..\$_\skills"
219.             if (Test-Path $src) {
220.                 Get-ChildItem $src -Directory | Where-Object { !(Test-Path (Join-Path $skillsDst $_.Name)) } |
221.                     ForEach-Object { Move-Item $_.FullName $skillsDst }
222.                 if ((Get-ChildItem $src -Force | Measure-Object).Count -eq 0) { Remove-Item $src -Force }
223.             }
224.             $root = Join-Path $PSScriptRoot "..\$_"
225.             if ((Test-Path $root) -and ((Get-ChildItem $root -Force | Measure-Object).Count -eq 0)) { Remove-Item $root -Force }
226.         }
227.     } catch {
228.         Write-Warning "Entire skills install failed: $($_.Exception.Message)"
229.     }
230. }
231. 
232. $results = [System.Collections.Generic.List[object]]::new()
233. 
234. $requirements = @{
235.     "az"         = "2.88.0"
236.     "azd"        = "1.29.0"
237.     "node"       = "22.0.0"
238.     "npm"        = "11.0.0"
239.     "pac"        = "2.9.3"
240.     "dotnet"     = "8.0.0"
241.     "gh"         = "2.96.0"
242.     "gh-stack"   = "0.1.0"
243.     "dataverse"  = "1.0.59"
244.     "plugin-dv"  = "1.10.0"
245.     "plugin-cps" = "1.0.11"
246.     "plugin-cap" = "1.1.0"
247.     "plugin-pa"  = "2.3.1"
248.     "plugin-mcs" = "1.0.2"
249.     "entire"     = "0.9.0"
250. }
251. 
252. $azRaw = Get-CommandTextOutput -Name "az" -CommandArgs @("version", "--output", "json")
253. $azVersion = $null
254. if ($azRaw) {
255.     try {
256.         $azObj = $azRaw | ConvertFrom-Json
257.         $azVersion = $azObj."azure-cli"
258.     } catch {
259.         $azVersion = Parse-VersionFromRegex -InputText $azRaw -Pattern 'azure-cli[^0-9]*([0-9]+\.[0-9]+\.[0-9]+)'
260.     }
261. }
262. 
263. $azdRaw = Get-CommandTextOutput -Name "azd" -CommandArgs @("version")
264. $azdVersion = Parse-VersionFromRegex -InputText $azdRaw -Pattern 'azd version ([0-9]+\.[0-9]+\.[0-9]+)'
265. 
266. $nodeRaw = Get-CommandTextOutput -Name "node" -CommandArgs @("--version")
267. $nodeVersion = if ($nodeRaw) { $nodeRaw.TrimStart('v') } else { $null }
268. 
269. $npmRaw = Get-CommandTextOutput -Name "npm" -CommandArgs @("--version")
270. $npmVersion = if ($npmRaw) { $npmRaw.Trim() } else { $null }
271. 
272. $pacRaw = Get-CommandTextOutput -Name "pac"
273. $pacVersion = Parse-VersionFromRegex -InputText $pacRaw -Pattern 'Version:\s*([0-9]+\.[0-9]+\.[0-9]+)'
274. 
275. $dotnetRaw = Get-CommandTextOutput -Name "dotnet" -CommandArgs @("--version")
276. $dotnetVersion = if ($dotnetRaw) { $dotnetRaw.Trim() } else { $null }
277. 
278. $ghRaw = Get-CommandTextOutput -Name "gh" -CommandArgs @("--version")
279. $ghVersion = Parse-VersionFromRegex -InputText $ghRaw -Pattern 'gh version ([0-9]+\.[0-9]+\.[0-9]+)'
280. 
281. $gitRaw = Get-CommandTextOutput -Name "git" -CommandArgs @("--version")
282. $gitVersion = Parse-VersionFromRegex -InputText $gitRaw -Pattern 'git version ([0-9]+\.[0-9]+\.[0-9]+)'
283. 
284. $ghExtRaw = Get-CommandTextOutput -Name "gh" -CommandArgs @("extension", "list")
285. $ghStackVersion = $null
286. if ($ghExtRaw) {
287.     $ghStackVersion = Parse-VersionFromRegex -InputText $ghExtRaw -Pattern 'gh stack\s+github/gh-stack\s+v([0-9]+\.[0-9]+\.[0-9]+)'
288. }
289. 
290. $dataverseInstalledRaw = Get-CommandTextOutput -Name "npm" -CommandArgs @("list", "-g", "@microsoft/dataverse", "--depth=0")
291. $dataverseInstalledVersion = Parse-VersionFromRegex -InputText $dataverseInstalledRaw -Pattern '@microsoft/dataverse@([0-9]+\.[0-9]+\.[0-9]+)'
292. 
293. $dataverseLatestRaw = Get-CommandTextOutput -Name "npm" -CommandArgs @("view", "@microsoft/dataverse", "version")
294. $dataverseLatestVersion = if ($dataverseLatestRaw) { $dataverseLatestRaw.Trim() } else { $null }
295. 
296. $copilotPluginsRaw = Get-CommandTextOutput -Name "copilot" -CommandArgs @("plugin", "list")
297. $plugins = @{}
298. if ($copilotPluginsRaw) {
299.     $normalizedCopilotPlugins = Remove-Ansi $copilotPluginsRaw
300.     # Be tolerant to terminal rendering differences (bullet glyph, asterisk, dash, or plain text).
301.     $matches = [regex]::Matches(
302.         $normalizedCopilotPlugins,
303.         '(?im)^\s*(?:[•\-\*]\s+)?([a-z0-9][a-z0-9\-]*)@([a-z0-9][a-z0-9\-]*)\s+\(v([0-9]+\.[0-9]+\.[0-9]+)\)\s*$'
304.     )
305.     if ($matches.Count -eq 0) {
306.         # Fallback to non-anchored scan in case the host injects extra prefix text per line.
307.         $matches = [regex]::Matches(
308.             $normalizedCopilotPlugins,
309.             '(?i)([a-z0-9][a-z0-9\-]*)@([a-z0-9][a-z0-9\-]*)\s+\(v([0-9]+\.[0-9]+\.[0-9]+)\)'
310.         )
311.     }
312.     foreach ($m in $matches) {
313.         $key = "$($m.Groups[1].Value)@$($m.Groups[2].Value)"
314.         $plugins[$key] = $m.Groups[3].Value
315.     }
316. }
317. 
318. $entireRaw = Get-CommandTextOutput -Name "entire" -CommandArgs @("--version")
319. $entireVersion = Parse-VersionFromRegex -InputText $entireRaw -Pattern 'Entire CLI ([0-9]+\.[0-9]+\.[0-9]+)'
320. 
321. $gitRemoteEntireRaw = Get-CommandTextOutput -Name "git-remote-entire" -CommandArgs @("--version")
322. $gitRemoteEntireVersion = Parse-VersionFromRegex -InputText $gitRemoteEntireRaw -Pattern 'git-remote-entire ([0-9]+\.[0-9]+\.[0-9]+)'
323. 
324. $toolChecks = @(
325.     @{ Name = "az"; Installed = $azVersion; Required = $requirements.az; Category = "Tooling" },
326.     @{ Name = "azd"; Installed = $azdVersion; Required = $requirements.azd; Category = "Tooling" },
327.     @{ Name = "node"; Installed = $nodeVersion; Required = $requirements.node; Category = "Tooling" },
328.     @{ Name = "npm"; Installed = $npmVersion; Required = $requirements.npm; Category = "Tooling" },
329.     @{ Name = "pac"; Installed = $pacVersion; Required = $requirements.pac; Category = "Tooling" },
330.     @{ Name = "dotnet"; Installed = $dotnetVersion; Required = $requirements.dotnet; Category = "Tooling" },
331.     @{ Name = "gh"; Installed = $ghVersion; Required = $requirements.gh; Category = "Tooling" },
332.     @{ Name = "git"; Installed = $gitVersion; Required = "2.0.0"; Category = "Tooling" },
333.     @{ Name = "gh-stack"; Installed = $ghStackVersion; Required = $requirements."gh-stack"; Category = "Extensions" },
334.     @{ Name = "@microsoft/dataverse"; Installed = $dataverseInstalledVersion; Required = $requirements.dataverse; Category = "Tooling" },
335.     @{ Name = "entire"; Installed = $entireVersion; Required = $requirements.entire; Category = "Entire" },
336.     @{ Name = "git-remote-entire"; Installed = $gitRemoteEntireVersion; Required = $requirements.entire; Category = "Entire" }
337. )
338. 
339. foreach ($check in $toolChecks) {
340.     if ([string]::IsNullOrWhiteSpace($check.Installed)) {
341.         Add-Result -List $results -Category $check.Category -Name $check.Name -Installed "-" -Required $check.Required -Status "FAIL" -Notes "Not detected"
342.         continue
343.     }
344.     $ok = Compare-Version -Actual $check.Installed -Minimum $check.Required
345.     if ($ok -eq $true) {
346.         $notes = ""
347.         if ($check.Name -eq "@microsoft/dataverse" -and $dataverseLatestVersion) {
348.             $notes = "latest=$dataverseLatestVersion"
349.         }
350.         Add-Result -List $results -Category $check.Category -Name $check.Name -Installed $check.Installed -Required $check.Required -Status "OK" -Notes $notes
351.     } elseif ($ok -eq $false) {
352.         Add-Result -List $results -Category $check.Category -Name $check.Name -Installed $check.Installed -Required $check.Required -Status "WARN" -Notes "Below recommended baseline"
353.     } else {
354.         Add-Result -List $results -Category $check.Category -Name $check.Name -Installed $check.Installed -Required $check.Required -Status "WARN" -Notes "Version parse issue"
355.     }
356. }
357. 
358. $pluginChecks = @(
359.     @{ Key = "dataverse@awesome-copilot"; Required = $requirements."plugin-dv" },
360.     @{ Key = "copilot-studio@skills-for-copilot-studio"; Required = $requirements."plugin-cps" },
361.     @{ Key = "code-apps-preview@power-platform-skills"; Required = $requirements."plugin-cap" },
362.     @{ Key = "power-automate@power-platform-skills"; Required = $requirements."plugin-pa" },
363.     @{ Key = "mcs-assistant@copilot-studio-plugin"; Required = $requirements."plugin-mcs" }
364. )
365. 
366. foreach ($p in $pluginChecks) {
367.     $installed = $null
368.     if ($plugins.ContainsKey($p.Key)) { $installed = $plugins[$p.Key] }
369.     if (-not $installed) { $installed = Get-PluginVersionFromLocalInstall -PluginKey $p.Key }
370.     if (-not $installed) {
371.         Add-Result -List $results -Category "Plugins" -Name $p.Key -Installed "-" -Required $p.Required -Status "FAIL" -Notes "Plugin not installed"
372.         continue
373.     }
374.     $ok = Compare-Version -Actual $installed -Minimum $p.Required
375.     $status = if ($ok -eq $true) { "OK" } else { "WARN" }
376.     $notes = if ($ok -eq $true) { "" } else { "Below recommended baseline" }
377.     Add-Result -List $results -Category "Plugins" -Name $p.Key -Installed $installed -Required $p.Required -Status $status -Notes $notes
378. }
379. 
380. if (Test-Path Env:GITHUB_TOKEN) {
381.     $ghAuth = Get-CommandTextOutput -Name "gh" -CommandArgs @("auth", "status")
382.     if ($ghAuth -and $ghAuth -match 'token in GITHUB_TOKEN is invalid') {
383.         Add-Result -List $results -Category "Auth" -Name "GITHUB_TOKEN precedence" -Installed "invalid env token detected" -Required "unset or valid token" -Status "WARN" -Notes "Run with -FixGhAuth or remove env var"
384.     }
385. }
386. 
387. # Entire repo readiness
388. $entireSettingsPath = Join-Path $PSScriptRoot "..\\.entire\settings.json"
389. $entireEnabled = $false
390. if (Test-Path $entireSettingsPath) {
391.     try {
392.         $entireSettings = Get-Content $entireSettingsPath -Raw | ConvertFrom-Json
393.         $entireEnabled = $entireSettings.enabled -eq $true
394.     } catch { }
395. }
396. $entireEnabledStatus = if ($entireEnabled) { "OK" } else { "FAIL" }
397. $entireEnabledNotes = if ($entireEnabled) { "" } else { "Run: entire enable -y --agent copilot-cli" }
398. $entireEnabledInstalled = if ($entireEnabled) { "true" } else { "-" }
399. Add-Result -List $results -Category "Entire" -Name "repo enabled (.entire/settings.json)" -Installed $entireEnabledInstalled -Required "true" -Status $entireEnabledStatus -Notes $entireEnabledNotes
400. 
401. $hooksDir = Join-Path $PSScriptRoot "..\.git\hooks"
402. if (!(Test-Path $hooksDir)) {
403.     # worktree: .git is a file pointing to .git/worktrees/<name>; hooks are in main .git/hooks
404.     $gitFile = Join-Path $PSScriptRoot "..\.git"
405.     if (Test-Path $gitFile -PathType Leaf) {
406.         $gitFileContent = Get-Content $gitFile -Raw
407.         $m = [regex]::Match($gitFileContent, 'gitdir:\s*(.+)')
408.         if ($m.Success) {
409.             # Traverse up: .git/worktrees/<name> -> .git -> hooks
410.             $worktreeGitDir = $m.Groups[1].Value.Trim()
411.             $mainGitDir = Split-Path (Split-Path $worktreeGitDir -Parent) -Parent
412.             $hooksDir = Join-Path $mainGitDir "hooks"
413.         }
414.     }
415. }
416. $entireHooks = @('commit-msg', 'post-commit', 'pre-push', 'prepare-commit-msg')
417. $installedHooks = @()
418. if (Test-Path $hooksDir) {
419.     $installedHooks = @(Get-ChildItem $hooksDir -Name | Where-Object { $_ -notmatch '\.sample$' })
420. }
421. $hooksOk = (@($entireHooks | Where-Object { $installedHooks -contains $_ })).Count -eq $entireHooks.Count
422. $hooksStatus = if ($hooksOk) { "OK" } else { "FAIL" }
423. $hooksNotes = if ($hooksOk) { "" } else { "Run: entire enable -y --agent copilot-cli" }
424. $hooksInstalled = if ($hooksOk) { "yes" } else { "-" }
425. Add-Result -List $results -Category "Entire" -Name "git hooks installed" -Installed $hooksInstalled -Required "yes" -Status $hooksStatus -Notes $hooksNotes
426. 
427. # Entire skills check
428. $expectedSkills = @('using-entire', 'what-happened', 'search', 'recall', 'replay', 'review', 'explain', 'teach', 'session-handoff', 'session-crosslink', 'session-to-skill', 'address-findings')
429. $skillsRoot = Join-Path $env:USERPROFILE '.copilot\skills'
430. $missingSkills = @($expectedSkills | Where-Object { !(Test-Path (Join-Path $skillsRoot $_)) })
431. $skillsOk = $missingSkills.Count -eq 0
432. $skillsStatus = if ($skillsOk) { "OK" } else { "WARN" }
433. $skillsNotes = if ($skillsOk) { "" } else { "Missing: $($missingSkills -join ', '). Run with -Setup or: npx skills add https://github.com/entireio/skills --all" }
434. $skillsInstalled = if ($skillsOk) { "$($expectedSkills.Count)/$($expectedSkills.Count)" } else { "$($expectedSkills.Count - $missingSkills.Count)/$($expectedSkills.Count)" }
435. Add-Result -List $results -Category "Entire" -Name "skills (~/.copilot/skills)" -Installed $skillsInstalled -Required "$($expectedSkills.Count)/$($expectedSkills.Count)" -Status $skillsStatus -Notes $skillsNotes
436. 
437. if ($Json) {
438.     $results | ConvertTo-Json -Depth 4
439. } else {
440.     Write-Host ""
441.     Write-Host "Tech stack readiness report" -ForegroundColor Cyan
442.     Write-Host "=========================="
443.     $results | Sort-Object Category, Name | Format-Table -AutoSize
444. 
445.     $failCount = @($results | Where-Object { $_.Status -eq "FAIL" }).Count
446.     $warnCount = @($results | Where-Object { $_.Status -eq "WARN" }).Count
447.     Write-Host ""
448.     if ($failCount -eq 0 -and $warnCount -eq 0) {
449.         Write-Host "Result: READY" -ForegroundColor Green
450.     } elseif ($failCount -eq 0) {
451.         Write-Host "Result: READY WITH WARNINGS ($warnCount warning(s))" -ForegroundColor Yellow
452.     } else {
453.         Write-Host "Result: NOT READY ($failCount fail(s), $warnCount warning(s))" -ForegroundColor Red
454.     }
455. }
456.

