     [switch]$Json,
     [Alias("h")]
     [switch]$Help,
     [Parameter(ValueFromRemainingArguments = $true)]
     [string[]]$RemainingArgs
 )

 Set-StrictMode -Version Latest
 $ErrorActionPreference = "Stop"

 function Show-Usage {
     Write-Host ""
     Write-Host "Tech stack readiness script" -ForegroundColor Cyan
     Write-Host "==========================="
     Write-Host ""
     Write-Host "Usage:"
     Write-Host "  .\scripts\tech-stack-readiness.ps1 [options]"
     Write-Host ""
     Write-Host "Options:"
     Write-Host "  -Setup       Run update/setup commands, then report readiness"
     Write-Host "  -FixGhAuth   Remove GITHUB_TOKEN from current session if set"
     Write-Host "  -Json        Output results as JSON"
     Write-Host "  -Help        Show this help"
     Write-Host ""
     Write-Host "Examples:"
     Write-Host "  .\scripts\tech-stack-readiness.ps1"
     Write-Host "  .\scripts\tech-stack-readiness.ps1 -Setup"
     Write-Host "  .\scripts\tech-stack-readiness.ps1 -FixGhAuth"
     Write-Host "  .\scripts\tech-stack-readiness.ps1 -Json"
     Write-Host "  .\scripts\tech-stack-readiness.ps1 --help"
     Write-Host ""
 }

 if ($Help -or ($RemainingArgs -contains "--help") -or ($RemainingArgs -contains "-h")) {
     Show-Usage
     return
 }

 function Normalize-Version {
     param([string]$Value)
     if ([string]::IsNullOrWhiteSpace($Value)) { return $null }
     $clean = $Value.Trim()
     $clean = $clean -replace '^[vV]', ''
     $clean = ($clean -split '[+ -]')[0]
     try { return [version]$clean } catch { return $null }
 }

 function Compare-Version {
     param(
         [string]$Actual,
         [string]$Minimum
     )
     $a = Normalize-Version $Actual
     $m = Normalize-Version $Minimum
     if (-not $a -or -not $m) { return $null }
     return ($a -ge $m)
 }

 function Get-CommandTextOutput {
     param(
         [string]$Name,
         [string[]]$CommandArgs = @()
     )
     try {
         $null = Get-Command $Name -ErrorAction Stop
         return (& $Name @CommandArgs 2>&1 | Out-String).Trim()
     } catch {
         return $null
     }
 }

 function Add-Result {
     param(
         [System.Collections.Generic.List[object]]$List,
         [string]$Category,
         [string]$Name,
         [string]$Installed,
         [string]$Required,
         [string]$Status,
         [string]$Notes
     )
     $List.Add([pscustomobject]@{
             Category  = $Category
             Name      = $Name
             Installed = $Installed
             Required  = $Required
             Status    = $Status
             Notes     = $Notes
         })
 }

 function Parse-VersionFromRegex {
     param(
         [string]$InputText,
         [string]$Pattern
     )
     if ([string]::IsNullOrWhiteSpace($InputText)) { return $null }
     $m = [regex]::Match($InputText, $Pattern)
     if ($m.Success -and $m.Groups.Count -gt 1) { return $m.Groups[1].Value.Trim() }
     return $null
 }

 function Remove-Ansi {
     param([string]$Text)
     if ($null -eq $Text) { return $null }
     return ($Text -replace '\x1B\[[0-9;?]*[ -/]*[@-~]', '')
 }

 function Get-PluginVersionFromLocalInstall {
     param([string]$PluginKey)

     $parts = $PluginKey.Split("@")
     if ($parts.Count -ne 2) { return $null }
     $pluginName = $parts[0]
     $marketplace = $parts[1]

     $root = Join-Path $env:USERPROFILE ".copilot\installed-plugins\$marketplace\$pluginName"
     if (-not (Test-Path $root)) { return $null }

     $jsonCandidates = Get-ChildItem $root -Recurse -Filter "plugin.json" -ErrorAction SilentlyContinue
     foreach ($file in $jsonCandidates) {
         try {
             $obj = Get-Content $file.FullName -Raw | ConvertFrom-Json
             if ($obj.name -eq $pluginName -and $obj.version) {
                 return [string]$obj.version
             }
         } catch {
             continue
         }
     }
     return $null
 }

 if ($FixGhAuth -and (Test-Path Env:GITHUB_TOKEN)) {
     Remove-Item Env:GITHUB_TOKEN -ErrorAction SilentlyContinue
     Write-Host "Removed GITHUB_TOKEN from current session environment."
 }

 if ($Setup) {
     Write-Host "Running update/setup actions..." -ForegroundColor Cyan

     $wingetIds = @(
         "Microsoft.AzureCLI",
         "Microsoft.Azd",
         "OpenJS.NodeJS.22",
