 )

 foreach ($check in $toolChecks) {
     if ([string]::IsNullOrWhiteSpace($check.Installed)) {
         Add-Result -List $results -Category $check.Category -Name $check.Name -Installed "-" -Required $check.Required -Status "FAIL" -Notes "Not detected"
