{"file_text":"<#
.SYNOPSIS
    Reports Entire observability metrics for the current session/branch.

.DESCRIPTION
    Collects and reports data points about the Entire integration:
      - Entire CLI availability and version
      - Whether Entire is enabled in the repo
      - Whether the current HEAD commit carries an Entire-Checkpoint trailer
      - Session linkage status (resolved via Resolve-CopilotSession.ps1)
      - Git hooks installation

    The -Stage parameter allows downstream callers to label the context in
    which the check is being performed (e.g. 'manual', 'pre-push', 'post-merge').

.PARAMETER Stage
    Label for the observability stage. Used in output headers only; does not
    alter behavior. Typical values: manual, pre-push, post-merge, finalize.

.PARAMETER Json
    Emit results as JSON instead of a human-readable table.

.EXAMPLE
    .\scripts\entire-integration\Invoke-EntireObservability.ps1 -Stage manual
    .\scripts\entire-integration\Invoke-EntireObservability.ps1 -Stage pre-push -Json
#>

[CmdletBinding()]
param(
    [string]$Stage = "manual",
    [switch]$Json
)

Set-StrictMode -Version Latest
$ErrorActionPreference = "Stop"

$scriptDir = Split-Path $MyInvocation.MyCommand.Path -Parent
$resolverScript = Join-Path $scriptDir "Resolve-CopilotSession.ps1"

function Get-CommandTextOutput {
    param([string]$Name, [string[]]$CommandArgs = @())
    try {
        $null = Get-Command $Name -ErrorAction Stop
        return (& $Name @CommandArgs 2>&1 | Out-String).Trim()
    } catch {
        return $null
    }
}

$checks = [System.Collections.Generic.List[object]]::new()

function Add-Check {
    param([string]$Area, [string]$Name, [string]$Value, [string]$Status, [string]$Notes = "")
    $checks.Add([pscustomobject]@{
        Area   = $Area
        Name   = $Name
        Value  = $Value
        Status = $Status
        Notes  = $Notes
    })
}

# --- Entire CLI ---
$entireRaw = Get-CommandTextOutput -Name "entire" -CommandArgs @("--version")
if ($entireRaw) {
    $m = [regex]::Match($entireRaw, 'Entire CLI ([0-9]+\.[0-9]+\.[0-9]+)')
    $ver = if ($m.Success) { $m.Groups[1].Value } else { $entireRaw.Substring(0, [Math]::Min(40,$entireRaw.Length)) }
    Add-Check -Area "CLI" -Name "entire" -Value $ver -Status "OK"
} else {
    Add-Check -Area "CLI" -Name "entire" -Value "-" -Status "FAIL" -Notes "Not installed or not on PATH"
}

# --- Repo enabled ---
$settingsPath = Join-Path (git rev-parse --show-toplevel 2>$null) ".entire\settings.json"
$repoEnabled = $false
if (Test-Path $settingsPath) {
    try {
        $s = Get-Content $settingsPath -Raw | ConvertFrom-Json
        $repoEnabled = $s.enabled -eq $true
        $commitLinking = $s.commit_linking
    } catch { }
}
Add-Check -Area "Repo" -Name "enabled" -Value ($repoEnabled.ToString().ToLower()) `
    -Status (if ($repoEnabled) { "OK" } else { "FAIL" }) `
    -Notes (if (-not $repoEnabled) { "Run: entire enable -y --agent copilot-cli" } else { "" })

if ($repoEnabled) {
    $clOk = ($commitLinking -eq "always")
    Add-Check -Area "Repo" -Name "commit_linking" -Value $commitLinking `
        -Status (if ($clOk) { "OK" } else { "WARN" }) `
        -Notes (if (-not $clOk) { "Set commit_linking: always in .entire/settings.json" } else { "" })
}

# --- HEAD trailer ---
$headMsg = (git log -1 --format="%B" 2>$null | Out-String).Trim()
$hasTrailer = $headMsg -match 'Entire-Checkpoint:'
$headSha = (git rev-parse --short HEAD 2>$null).Trim()
Add-Check -Area "Commit" -Name "HEAD trailer ($headSha)" `
    -Value (if ($hasTrailer) { "present" } else { "missing" }) `
    -Status (if ($hasTrailer) { "OK" } else { "WARN" }) `
    -Notes (if (-not $hasTrailer) { "Run Invoke-EntireStackFinalize.ps1 to attach" } else { "" })

# --- Session resolution ---
$sessionId = $null
$sessionBranchMatch = $false
if (Test-Path $resolverScript) {
    try {
        $sessionJson = (& powershell -NoProfile -ExecutionPolicy Bypass -File $resolverScript -Json 2>&1 | Out-String).Trim()
        $sessionObj = $sessionJson | ConvertFrom-Json
        if ($sessionObj.SessionId) {
            $sessionId = $sessionObj.SessionId
            $sessionBranchMatch = $sessionObj.BranchMatch
            Add-Check -Area "Session" -Name "resolved" -Value $sessionId `
                -Status "OK" `
                -Notes (if (-not $sessionBranchMatch) { "Branch mismatch — best-effort match" } else { "" })
        } else {
            Add-Check -Area "Session" -Name "resolved" -Value "-" -Status "FAIL" -Notes "Could not resolve session ID"
        }
    } catch {
        Add-Check -Area "Session" -Name "resolved" -Value "-" -Status "FAIL" -Notes $_.Exception.Message
    }
} else {
    Add-Check -Area "Session" -Name "resolved" -Value "-" -Status "FAIL" -Notes "Resolve-CopilotSession.ps1 not found"
}

# --- Git hooks ---
$gitDir = (git rev-parse --git-dir 2>$null).Trim()
$hooksDir = Join-Path $gitDir "hooks"
if (-not (Test-Path $hooksDir)) {
    # worktree: .git is a file; walk up to main .git/hooks
    if (Test-Path $gitDir -PathType Leaf) {
        $content = Get-Content $gitDir -Raw
        $m = [regex]::Match($content, 'gitdir:\s*(.+)')
        if ($m.Success) {
            $mainGit = Split-Path (Split-Path $m.Groups[1].Value.Trim() -Parent) -Parent
            $hooksDir = Join-Path $mainGit "hooks"
        }
    }
}
$expectedHooks = @('commit-msg', 'post-commit', 'pre-push', 'prepare-commit-msg')
if (Test-Path $hooksDir) {
    $installed = @(Get-ChildItem $hooksDir -Name | Where-Object { $_ -notmatch '\.sample$' })
    $missing = @($expectedHooks | Where-Object { $installed -notcontains $_ })
    $hooksOk = $missing.Count -eq 0
    Add-Check -Area "Repo" -Name "git hooks" -Value (if ($hooksOk) { "all present" } else { "$($expectedHooks.Count - $missing.Count)/$($expectedHooks.Count)" }) `
        -Status (if ($hooksOk) { "OK" } else { "FAIL" }) `
        -Notes (if (-not $hooksOk) { "Missing: $($missing -join ', '). Run: entire enable -y --agent copilot-cli" } else { "" })
} else {
    Add-Check -Area "Repo" -Name "git hooks" -Value "-" -Status "WARN" -Notes "hooks dir not found: $hooksDir"
}

# --- Output ---
$summary = [pscustomobject]@{
    Stage     = $Stage
    Timestamp = (Get-Date -Format "o")
    SessionId = $sessionId
    Checks    = $checks
    FailCount = @($checks | Where-Object { $_.Status -eq "FAIL" }).Count
    WarnCount = @($checks | Where-Object { $_.Status -eq "WARN" }).Count
}

if ($Json) {
    $summary | ConvertTo-Json -Depth 5
} else {
    Write-Host ""
    Write-Host "Entire Observability  [stage: $Stage]" -ForegroundColor Cyan
    Write-Host "======================================"
    $checks | Format-Table Area, Name, Value, Status, Notes -AutoSize
    $failCount = $summary.FailCount
    $warnCount = $summary.WarnCount
    if ($failCount -eq 0 -and $warnCount -eq 0) {
        Write-Host "Overall: HEALTHY" -ForegroundColor Green
    } elseif ($failCount -eq 0) {
        Write-Host "Overall: WARN ($warnCount warning(s))" -ForegroundColor Yellow
    } else {
        Write-Host "Overall: DEGRADED ($failCount fail(s), $warnCount warning(s))" -ForegroundColor Red
    }
    Write-Host ""
}
